// requestTimeout bounds one lookup attempt.
const requestTimeout = 10 * time.Second

// maxRetries is how many times a failed lookup is repeated.
// 生成失敗時は正確に 1 回だけ再試行する（初回 + 再試行 1 回 = 最大 2 回の呼び出し）。
// maxRetries は Fetch の再試行回数(初回を除く)。SetMaxRetries で変更できる。
var maxRetries = 1

// SetMaxRetries は再試行回数を設定する。負数は 0 として扱う。
func SetMaxRetries(n int) {
	if n < 0 {
		n = 0
	}
	maxRetries = n
}

